// AgentSessionDiscovery returns a detached, contract-derived operation registry.
func AgentSessionDiscovery() json.RawMessage { return json.RawMessage(agentSessionRegistryJSON) }

type AgentSession struct {
	client         *Client
	provider       AgentProvider
	options        AgentSessionOptions
	registry       map[string]agentSessionOperation
	schemas        map[string]any
	allowed        map[string]bool
	state          *agentSessionState
	mu             sync.Mutex
	running        bool
	storageFailure error
}

func agentSessionCount(key string) bool { return key != "cost" && key != "elapsed_seconds" }
func NewAgentSession(client *Client, provider AgentProvider, options AgentSessionOptions) (*AgentSession, error) {
	if client == nil || provider == nil || options.Checkpoint == nil || options.PersistResult == nil || options.ApproveWrite == nil {
		return nil, agentRefused("client, provider, checkpoint and policy callbacks required", nil)
	}
	if len(options.Limits) != len(agentSessionLimitKeys) {
		return nil, agentRefused("all nine budgets required", nil)
	}
	limits := AgentLimits{}
	for _, key := range agentSessionLimitKeys {
		v := options.Limits[key]
		if !(v > 0) || math.IsInf(v, 0) || math.IsNaN(v) || (agentSessionCount(key) && (math.Trunc(v) != v || v > 9007199254740991)) {
			return nil, agentRefused("positive finite budgets and safe integer counts required", nil)
		}
		limits[key] = v
	}
	options.Limits = limits
	digest, err := hex.DecodeString(options.ArtifactHash)
	if err != nil || len(digest) != 32 || strings.ToLower(options.ArtifactHash) != options.ArtifactHash || provider.Version() != AgentProviderProtocol || provider.Identity() == "" {
		return nil, agentRefused("provider identity and exact archive hash required", err)
	}
	s := &AgentSession{client: client, provider: provider, options: options, allowed: map[string]bool{}}
	if err = json.Unmarshal([]byte(agentSessionRegistryJSON), &s.registry); err != nil {
		return nil, err
	}
	if err = json.Unmarshal([]byte(agentSessionSchemasJSON), &s.schemas); err != nil {
		return nil, err
	}
	allowed := append([]string(nil), options.AllowedTools...)
	sort.Strings(allowed)
	if len(allowed) == 0 {
		return nil, agentRefused("explicit nonempty operation allowlist required", nil)
	}
	for _, tool := range allowed {
		if _, ok := s.registry[tool]; !ok || s.allowed[tool] {
			return nil, agentRefused("unknown or duplicate allowed operation", nil)
		}
		s.allowed[tool] = true
	}
	binding, err := agentSessionJSON(map[string]any{"version": AgentSessionProtocol, "language": "go", "source": AgentSessionSource, "artifact": options.ArtifactHash, "registry": agentSessionDigest([]byte(agentSessionRegistryJSON)), "provider": map[string]string{"identity": provider.Identity(), "version": provider.Version()}, "limits": limits, "allowed_tools": allowed})
	if err != nil {
		return nil, err
	}
	s.state, err = options.Checkpoint.load()
	if err != nil {
		return nil, err
	}
	if s.state == nil {
		s.state = &agentSessionState{Binding: binding, Used: AgentLimits{}, ObservedUsage: AgentLimits{"tokens": 0, "cost": 0}, Receipts: []AgentReceipt{}, Pending: []agentSessionPending{}}
		for _, key := range agentSessionLimitKeys {
			s.state.Used[key] = 0
		}
	}
	if !bytes.Equal(s.state.Binding, binding) || len(s.state.Used) != len(limits) {
		return nil, agentRefused("stale or mixed checkpoint", nil)
	}
	for key, limit := range limits {
		v, ok := s.state.Used[key]
		if !ok || v < 0 || v > limit || math.IsNaN(v) || math.IsInf(v, 0) || (agentSessionCount(key) && math.Trunc(v) != v) {
			return nil, agentRefused("corrupt budget state", nil)
		}
	}
	if s.state.ObservedUsage == nil || s.state.Deadline < 0 || math.IsInf(s.state.Deadline, 0) || math.IsNaN(s.state.Deadline) {
		return nil, agentRefused("corrupt usage or deadline", nil)
	}
	for key, value := range s.state.ObservedUsage {
		if (key != "tokens" && key != "cost" && key != "elapsed_seconds") || value < 0 || math.IsNaN(value) || math.IsInf(value, 0) {
			return nil, agentRefused("corrupt observed usage", nil)
		}
	}
	seen := map[string]bool{}
	previous := strings.Repeat("0", 64)
	for _, receipt := range s.state.Receipts {
		h := receipt.Hash
		receipt.Hash = ""
		raw, err := agentSessionJSON(receipt)
		if err != nil || receipt.Previous != previous || h != agentSessionDigest(raw) || seen[receipt.ID] || !s.allowed[receipt.Tool] {
			return nil, agentRefused("corrupt receipt chain", err)
		}
		seen[receipt.ID] = true
		previous = h
	}
	for _, pending := range s.state.Pending {
		if pending.ID == "" || seen[pending.ID] || !s.allowed[pending.Tool] || pending.Mutation != s.registry[pending.Tool].Mutation {
			return nil, agentRefused("corrupt pending call", nil)
		}
		seen[pending.ID] = true
	}
	if s.state.Final && (len(s.state.Pending) > 0 || s.state.FinalResult == nil) {
		return nil, agentRefused("corrupt final state", nil)
	}
	return s, nil
}
func (s *AgentSession) begin() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.running {
		return agentRefused("session already running", nil)
	}
	if s.storageFailure != nil {
		return agentRefused("checkpoint write failed; reload before continuing", s.storageFailure)
	}
	s.running = true
	return nil
}
func (s *AgentSession) end() { s.mu.Lock(); defer s.mu.Unlock(); s.running = false }
func (s *AgentSession) charge(key string, amount float64) error {
	if amount < 0 || math.IsNaN(amount) || math.IsInf(amount, 0) || s.state.Used[key]+amount > s.options.Limits[key] {
		return agentRefused("budget exceeded: "+key, nil)
	}
	s.state.Used[key] += amount
	return nil
}
func (s *AgentSession) persist() error {
	err := s.options.Checkpoint.save(s.state)
	if err != nil {
		s.storageFailure = err
	}
	return err
}
func (s *AgentSession) project(tool string, result any) (json.RawMessage, error) {
	safe, err := s.options.PersistResult(tool, result)
	if err != nil {
		return nil, err
	}
	data, err := agentSessionJSON(safe)
	if err != nil {
		return nil, err
	}
	if err = s.charge("output_bytes", float64(len(data))); err != nil {
		return nil, err
	}
	return data, nil
}
func (s *AgentSession) ack(call agentSessionPending, result any) error {
	priorReceipts := append([]AgentReceipt(nil), s.state.Receipts...)
	priorPending := append([]agentSessionPending(nil), s.state.Pending...)
	safe, err := s.project(call.Tool, result)
	if err != nil {
		return err
	}
	previous := strings.Repeat("0", 64)
	if len(s.state.Receipts) > 0 {
		previous = s.state.Receipts[len(s.state.Receipts)-1].Hash
	}
	receipt := AgentReceipt{ID: call.ID, Tool: call.Tool, ArgumentsHash: call.ArgumentsHash, Mutation: call.Mutation, Result: safe, Previous: previous}
	body, err := agentSessionJSON(receipt)
	if err != nil {
		return err
	}
	receipt.Hash = agentSessionDigest(body)
	s.state.Receipts = append(s.state.Receipts, receipt)
	pending := []agentSessionPending{}
	for _, item := range s.state.Pending {
		if item.ID != call.ID {
			pending = append(pending, item)
		}
	}
	s.state.Pending = pending
	if err = s.persist(); err != nil {
		s.state.Receipts = priorReceipts
		s.state.Pending = priorPending
		return err
	}
	return nil
}

// Reconcile records an externally verified result; it never invokes an SDK operation.
func (s *AgentSession) Reconcile(id string, result any) error {
	if err := s.begin(); err != nil {
		return err
	}
	defer s.end()
	for _, call := range s.state.Pending {
		if call.ID == id {
			return s.ack(call, result)
		}
	}
	return agentRefused("unknown in-doubt call", nil)
}

type agentSessionOutcome[T any] struct {
	value T
	err   error
}

func agentSessionAwait[T any](ctx context.Context, work func() (T, error)) (T, error) {
	var zero T
	if err := ctx.Err(); err != nil {
		return zero, err
	}
	done := make(chan agentSessionOutcome[T], 1)
	go func() {
		if err := ctx.Err(); err != nil {
			done <- agentSessionOutcome[T]{err: err}
			return
		}
		value, err := work()
		done <- agentSessionOutcome[T]{value, err}
	}()
	select {
	case result := <-done:
		return result.value, result.err
	case <-ctx.Done():
		return zero, ctx.Err()
	}
}

// Run executes ordered, bounded batches. Credentials and destination stay on the caller's client.
func (s *AgentSession) Run(ctx context.Context, input json.RawMessage) (result json.RawMessage, failure error) {
	if ctx == nil {
		return nil, agentRefused("context required", nil)
	}
	if err := s.begin(); err != nil {
		return nil, err
	}
	defer s.end()
	if len(s.state.Pending) > 0 {
		return nil, agentInDoubt(nil)
	}
	if s.state.Final {
		return append(json.RawMessage(nil), s.state.FinalResult...), nil
	}
	started := time.Now()
	remaining := s.options.Limits["elapsed_seconds"] - s.state.Used["elapsed_seconds"]
	if s.state.Deadline == 0 {
		s.state.Deadline = float64(started.UnixMilli())/1000 + remaining
	}
	remaining = math.Min(remaining, s.state.Deadline-float64(time.Now().UnixMilli())/1000)
	// Saturate before duration conversion: very large finite budgets must not overflow.
	ctx, cancel := context.WithTimeout(ctx, time.Duration(math.Min(math.Max(0, remaining), float64(math.MaxInt64/2)/float64(time.Second))*float64(time.Second)))
	defer cancel()
	defer func() {
		cancel()
		elapsed := s.state.Used["elapsed_seconds"] + time.Since(started).Seconds()
		s.state.ObservedUsage["elapsed_seconds"] = elapsed
		s.state.Used["elapsed_seconds"] = math.Min(s.options.Limits["elapsed_seconds"], elapsed)
		failure = errors.Join(failure, s.persist())
		cleanup, stop := context.WithTimeout(context.Background(), time.Duration(math.Min(1, s.options.Limits["elapsed_seconds"])*float64(time.Second)))
		defer stop()
		_, err := agentSessionAwait(cleanup, func() (bool, error) { return true, s.provider.Close(cleanup) })
		if err != nil {
			failure = errors.Join(failure, agentRefused("provider cleanup failed; callbacks remain caller-owned", err))
		}
		if failure != nil {
			for _, call := range s.state.Pending {
				if call.Mutation {
					failure = agentInDoubt(failure)
					break
				}
			}
			result = nil
		}
	}()
	if err := s.charge("input_bytes", float64(len(input))); err != nil {
		return nil, err
	}
	canonicalInput, err := agentSessionCanonical(input)
	if err != nil {
		return nil, err
	}
	for {
		if err = ctx.Err(); err != nil {
			return nil, err
		}
		if err = s.charge("turns", 1); err != nil {
			return nil, err
		}
		if err = s.charge("model_calls", 1); err != nil {
			return nil, err
		}
		if err = s.persist(); err != nil {
			return nil, err
		}
		tools := map[string]json.RawMessage{}
		var all map[string]json.RawMessage
		if err = json.Unmarshal([]byte(agentSessionRegistryJSON), &all); err != nil {
			return nil, err
		}
		for tool := range s.allowed {
			tools[tool] = all[tool]
		}
		toolJSON, err := json.Marshal(tools)
		if err != nil {
			return nil, err
		}
		contextJSON, err := agentSessionJSON(AgentContext{AgentSessionProtocol, canonicalInput, s.state.Receipts, toolJSON})
		if err != nil {
			return nil, err
		}
		if err = s.charge("input_bytes", float64(len(contextJSON))); err != nil {
			return nil, err
		}
		var proposalContext AgentContext
		if err = json.Unmarshal(contextJSON, &proposalContext); err != nil {
			return nil, err
		}
		remainingBudgets := AgentLimits{}
		for key, limit := range s.options.Limits {
			remainingBudgets[key] = limit - s.state.Used[key]
		}
		proposal, err := agentSessionAwait(ctx, func() (AgentProposal, error) { return s.provider.Propose(ctx, proposalContext, remainingBudgets) })
		if err != nil {
			return nil, err
		}
		if proposal.Final != nil && proposal.Calls != nil {
			return nil, agentRefused("proposal must contain calls or final, never both", nil)
		}
		encoded, err := agentSessionJSON(proposal)
		if err != nil {
			return nil, err
		}
		if err = s.charge("input_bytes", float64(len(encoded))); err != nil {
			return nil, err
		}
		// Detach provider-owned maps/slices before validating or dispatching.
		var detached AgentProposal
		if err = json.Unmarshal(encoded, &detached); err != nil {
			return nil, err
		}
		proposal = detached
		for key, value := range map[string]float64{"tokens": proposal.Usage.Tokens, "cost": proposal.Usage.Cost} {
			if value < 0 || math.IsNaN(value) || math.IsInf(value, 0) || (key == "tokens" && (math.Trunc(value) != value || value > 9007199254740991)) {
				return nil, agentRefused("invalid provider usage", nil)
			}
			s.state.ObservedUsage[key] += value
		}
		if err = s.charge("tokens", proposal.Usage.Tokens); err != nil {
			return nil, err
		}
		if err = s.charge("cost", proposal.Usage.Cost); err != nil {
			return nil, err
		}
		if proposal.Final != nil {
			if proposal.Calls != nil {
				return nil, agentRefused("proposal must contain calls or final, never both", nil)
			}
			value, err := agentSessionDecode(proposal.Final)
			if err != nil {
				return nil, err
			}
			safe, err := s.project("$final", value)
			if err != nil {
				return nil, err
			}
			s.state.Final = true
			s.state.FinalResult = safe
			if err = s.persist(); err != nil {
				return nil, err
			}
			return append(json.RawMessage(nil), safe...), nil
		}
		if len(proposal.Calls) == 0 || float64(len(proposal.Calls)) > s.options.Limits["concurrency"] {
			return nil, agentRefused("empty batch or concurrency budget exceeded", nil)
		}
		seen := map[string]bool{}
		for _, receipt := range s.state.Receipts {
			seen[receipt.ID] = true
		}
		pending := []agentSessionPending{}
		invocations := []agentSessionInvocation{}
		for _, call := range proposal.Calls {
			if call.ID == "" || seen[call.ID] || !s.allowed[call.Tool] || call.Arguments == nil {
				return nil, agentRefused("unknown tool, duplicate ID or malformed arguments", nil)
			}
			seen[call.ID] = true
			descriptor := s.registry[call.Tool]
			if descriptor.Execution != "buffered-json" {
				return nil, agentRefused("stream/upload operation is not qualified", nil)
			}
			fields := map[string]bool{}
			for _, arg := range descriptor.Arguments {
				fields[arg.Name] = true
				raw, exists := call.Arguments[arg.Name]
				if arg.Required && !exists {
					return nil, agentRefused("missing required argument", nil)
				}
				if exists {
					if arg.CallerOnly {
						return nil, agentRefused("header/cookie arguments require caller configuration", nil)
					}
					value, err := agentSessionDecode(raw)
					if err != nil {
						return nil, err
					}
					if err = agentSessionValidate(value, arg.Schema, s.schemas, 0); err != nil {
						return nil, err
					}
				}
			}
			for name := range call.Arguments {
				if !fields[name] {
					return nil, agentRefused("unknown argument; request options forbidden", nil)
				}
			}
			invoke, err := agentSessionPrepare(call)
			if err != nil {
				return nil, err
			}
			invocations = append(invocations, invoke)
			args, err := agentSessionJSON(call.Arguments)
			if err != nil {
				return nil, err
			}
			pending = append(pending, agentSessionPending{call.ID, call.Tool, agentSessionDigest(args), descriptor.Mutation})
		}
		if err = s.charge("tool_calls", float64(len(pending))); err != nil {
			return nil, err
		}
		for _, call := range pending {
			if call.Mutation {
				approved, err := agentSessionAwait(ctx, func() (bool, error) { return s.options.ApproveWrite(ctx, call.Tool, call.ArgumentsHash) })
				if err != nil {
					return nil, err
				}
				if !approved {
					return nil, agentRefused("explicit write approval required", nil)
				}
			}
		}
		if err = ctx.Err(); err != nil {
			return nil, err
		}
		s.state.Pending = pending
		if err = s.persist(); err != nil {
			return nil, err
		}
		responseBound := math.Min(64<<20, s.options.Limits["output_bytes"]-s.state.Used["output_bytes"])
		if responseBound < 1 {
			return nil, agentRefused("output budget exceeded", nil)
		}
		opts := []option.RequestOption{option.WithMaxRetries(0), option.WithMaxResponseBytes(int64(responseBound))}
		channels := make([]chan agentSessionOutcome[any], len(invocations))
		for i, invoke := range invocations {
			channels[i] = make(chan agentSessionOutcome[any], 1)
			go func(ch chan agentSessionOutcome[any], run agentSessionInvocation) {
				if err := ctx.Err(); err != nil {
					ch <- agentSessionOutcome[any]{err: err}
					return
				}
				value, err := run(ctx, s.client, opts)
				ch <- agentSessionOutcome[any]{value, err}
			}(channels[i], invoke)
		}
		values := make([]any, len(channels))
		for i, ch := range channels {
			select {
			case outcome := <-ch:
				if outcome.err != nil {
					return nil, outcome.err
				}
				values[i] = outcome.value
			case <-ctx.Done():
				return nil, ctx.Err()
			}
		}
		for i, value := range values {
			if err = s.ack(pending[i], value); err != nil {
				return nil, err
			}
		}
	}
}
